<?php require_once __DIR__.'/../includes/functions.php';role('teacher');$aid=(int)($_GET['id']??0);$tid=$_SESSION['user_id'];$s=$conn->prepare('SELECT a.*,c.title course FROM assignments a JOIN courses c ON c.id=a.course_id WHERE a.id=? AND a.teacher_id=?');$s->bind_param('ii',$aid,$tid);$s->execute();$a=$s->get_result()->fetch_assoc();if(!$a)exit('Assignment not found.');$s=$conn->prepare('SELECT s.*,u.name student FROM submissions s JOIN users u ON u.id=s.student_id WHERE s.assignment_id=? ORDER BY s.submitted_at DESC');$s->bind_param('i',$aid);$s->execute();$rows=$s->get_result();$page_title='Submissions';include __DIR__.'/../includes/header.php';?><h1>Submissions</h1><p><?=e($a['course'])?> · <?=e($a['title'])?></p><div class="card"><div class="tablewrap"><table><tr><th>Student</th><th>Response</th><th>File</th><th>Submitted</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['student'])?></td><td><?=nl2br(e($r['response_text']))?></td><td><?php if($r['stored_name']):?><a href="<?=BASE_URL?>/download.php?type=submission&id=<?=$r['id']?>"><?=e($r['original_name'])?></a><?php else:?>No file<?php endif;?></td><td><?=e($r['submitted_at'])?></td></tr><?php endwhile;?></table></div></div><?php include __DIR__.'/../includes/footer.php';?>
